(()=>{const e=document.getElementById("estado"),t=document.getElementById("cidade"),n=document.getElementById("cidade_destino");if(!e||!t)return;const l=t=>{if(!t)return;const n=e.value;t.querySelectorAll("optgroup").forEach(e=>{const t=!n||e.getAttribute("data-uf")===n;e.hidden=!t,e.querySelectorAll("option").forEach(e=>{e.disabled=!t})});const l=t.selectedOptions[0];l&&l.disabled&&(t.value="")},c=()=>{l(t),l(n)};e.addEventListener("change",c),c();const s=document.getElementById("pessoas");document.getElementById("menos")?.addEventListener("click",()=>{const e=Math.max(1,parseInt(s.value||"1",10)-1);s.value=String(e)}),document.getElementById("mais")?.addEventListener("click",()=>{const e=Math.min(16,parseInt(s.value||"1",10)+1);s.value=String(e)});const d=document.getElementById("whatsapp");d?.addEventListener("input",()=>{const e=d.value.replace(/\D/g,"").slice(0,11);e.length<=2?d.value=e.length?`(${e}`:"":e.length<=6?d.value=`(${e.slice(0,2)}) ${e.slice(2)}`:e.length<=10?d.value=`(${e.slice(0,2)}) ${e.slice(2,6)}-${e.slice(6)}`:d.value=`(${e.slice(0,2)}) ${e.slice(2,7)}-${e.slice(7)}`})})();